style.css:
body {
    background: linear-gradient(to bottom, #1a1a1a 0%, #333 40%, #1a1a1a 80%, #333 100%);
  background-size: cover;
    background-repeat: no-repeat;
    position: relative;
}

body::before {
  content: '';
  position: absolute;
  top: 30%;
  left: 10%;
  width: 80%;
    height: 2px;
    background: white;
     border-radius: 10%;
      opacity: 0.7;
   transform: rotate(-25deg);
   filter: blur(1px);
}
body::after{
    content: '';
    position: absolute;
    top: 40%;
    left: 20%;
    width: 40%;
    height: 2px;
    background: white;
    border-radius: 10%;
    opacity: 0.7;
      transform: rotate(-40deg);
      filter: blur(1px);
}
